fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    // Verify the input is valid UTF-8 and the length is a char boundary
    // This aligns with the recommends clause in the spec.

    // Use Rust's chars iterator to get Unicode scalar values
    let mut chars = txt.chars();

    // Attempt to get the last character, if any
    let last_char = match chars.next_back() {
        Some(c) => c,
        None => return false, // empty string
    };

    // Check if the last character is ASCII alphabetic
    let is_ascii_alpha = |c: char| ('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z');

    if !is_ascii_alpha(last_char) {
        return false;
    }

    // If there is exactly one character, then return true
    if txt.chars().count() == 1 {
        return true;
    }

    // Otherwise, check if the character before the last is a space
    // We can get an iterator over chars again, and get the nth from the end
    // but more straightforward: collect to vector of chars
    let chars_vec: Vec<char> = txt.chars().collect();

    // The character before the last is at chars_vec.len() - 2
    let is_space = |c: char| c == ' ';

    is_space(chars_vec[chars_vec.len() - 2])
}